/* Device-local demo. No network writes and no production financial records. */
(async function(){
 'use strict';
 const M=FinanceModel,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const amount=n=>n==null?'—':new Intl.NumberFormat('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
 const clockDate=new Date();const today=[clockDate.getFullYear(),String(clockDate.getMonth()+1).padStart(2,'0'),String(clockDate.getDate()).padStart(2,'0')].join('-');
 const id=()=>crypto.randomUUID();
 const seed={
  projects:[{id:'apartment',name:'Apartment renovation · Demo',client:'Demo Client A'},{id:'pool',name:'Swimming pool · Demo',client:'Demo Client B'}],
  payments:[{id:'PAY-001',project:'apartment',date:'2026-09-01',direction:'in',amount:300000,party:'Demo Client A',description:'Client advance',method:'Bank transfer',reference:'DEMO-001'},
   {id:'PAY-002',project:'apartment',date:'2026-09-02',direction:'out',amount:200000,party:'Demo supplier',description:'Materials payment',method:'Bank transfer',reference:'DEMO-002'},
   {id:'PAY-003',project:'pool',date:'2026-09-03',direction:'in',amount:150000,party:'Demo Client B',description:'Project advance',method:'Bank transfer',reference:'DEMO-003'}],
  expenses:[{id:'EXP-001',project:'apartment',date:'2026-09-02',amount:256959,category:'Materials',party:'Demo supplier',description:'Sample renovation costs',reference:'DEMO-EXP-1'},
   {id:'EXP-002',project:'pool',date:'2026-09-04',amount:100000,category:'Subcontractors',party:'Demo subcontractor',description:'Civil work completed',reference:'DEMO-EXP-2'}],
  charges:[{id:'CHG-001',project:'apartment',date:'2026-09-02',amount:256959,earned:256959,description:'Completed works charged to client'},
   {id:'CHG-002',project:'apartment',date:'2026-09-03',amount:38543.85,earned:38543.85,description:'Supervision fee · 15% of 256,959'},
   {id:'CHG-003',project:'apartment',date:'2026-09-03',amount:15000,earned:15000,description:'Engineering drawings'},
   {id:'CHG-004',project:'pool',date:'2026-09-04',amount:125000,earned:125000,description:'Completed civil milestone'}],
  invoices:[],quotes:[],
  blocks:[{id:'civil',name:'Pool · Civil works',items:[{description:'Concrete works',unit:'Lump sum',quantity:1,rate:110000},{description:'Waterproofing',unit:'m²',quantity:200,rate:450},{description:'Plastering',unit:'m²',quantity:125,rate:300},{description:'Mosaic finish',unit:'m²',quantity:125,rate:1050}]},
   {id:'equipment',name:'Pool · Equipment',items:[{description:'Sand filter',unit:'Item',quantity:1,rate:40000},{description:'Circulation pump',unit:'Item',quantity:2,rate:40000},{description:'Control panel',unit:'Lump sum',quantity:1,rate:50000}]},
   {id:'renovation',name:'Renovation · Services',items:[{description:'Electrical installation',unit:'Lump sum',quantity:1,rate:0},{description:'Plumbing installation',unit:'Lump sum',quantity:1,rate:0}]}]
 };
 let db,connection,tab='sheet',direction='in',filter={project:TrustSourceImport.projectId,from:'',to:''},draft=null,previousFocus,activeProject=null,projectTab='summary';
 try{
  connection=await new Promise((resolve,reject)=>{const r=indexedDB.open('trust-m-finance-demo-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('records');r.result.createObjectStore('files');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  db=await new Promise((resolve,reject)=>{const r=connection.transaction('records').objectStore('records').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  if(!db){db=structuredClone(seed);await persist(db);}
  const imported=structuredClone(db);if(TrustSourceImport.merge(imported,TrustSourceData)){await persist(imported);db=imported;}
 }catch(error){$('#finance-view').innerHTML='<p class="empty">Browser storage is unavailable. Open this demo in a standard browser window with local storage enabled.</p>';return;}
 function persist(next,file){return new Promise((resolve,reject)=>{const tx=connection.transaction(file?['records','files']:['records'],'readwrite');tx.objectStore('records').put(next,'workspace');if(file)tx.objectStore('files').put(file.blob,file.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Save cancelled'));});}
 async function change(fn,file){const next=structuredClone(db);fn(next);await persist(next,file);db=next;}
 const projectName=p=>db.projects.find(r=>r.id===p)?.name||'Company overhead';
 const projectOptions=(all=true)=>`${all?'<option value="all">All projects</option>':''}${db.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}`;
 const tabs=[['sheet','Financial sheet'],['projects','Project overview'],['reports','Reports · 18'],['quotes','Quotation blocks'],['payments','Payments'],['expenses','Expenses & charges'],['invoices','Invoices · فواتير'],['pnl','Profit & loss'],['statements','Client statements']];
 $('#finance-tabs').innerHTML=tabs.map(([key,label],i)=>`<button role="tab" id="tab-${key}" aria-controls="finance-view" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-tab="${key}">${label}</button>`).join('');
 $('#finance-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;render();}});
 $('#finance-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...$('#finance-tabs').children],i=buttons.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus();});
 function notice(s){$('#finance-status').textContent=s;}
 function saveDownload(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function csvDownload(name,rows){saveDownload(name+'.csv',M.csv(rows.map(row=>row.map(value=>typeof value==='string'?(window.egText?.(value)||value):value))));notice('Report downloaded. No message has been sent.');}
 function table(headers,rows){return `<div class="finance-table-wrap"><table class="finance-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No records match this selection.</td></tr>`}</tbody></table></div>`;}
 function kpis(items){return `<div class="finance-kpis">${items.map(([l,n])=>`<div class="kpi"><span>${l}</span><strong>${amount(n)}</strong><small>EGP</small></div>`).join('')}</div>`;}
 function head(title,note,button=''){return `<div class="finance-tools"><div><h2>${title}</h2><p>${note}</p></div>${button}</div>`;}
 function filters(single=false,period=false){return `<div class="filter-row"><label>Project<select id="filter-project">${projectOptions(!single)}</select></label>${period?'<label>Period<select id="period"><option value="custom">Custom / current</option><option value="all">All activity to date</option><option value="annual">Annual</option></select></label><label>Year<input id="report-year" type="number" min="2000" max="2100" value="2026"></label>':''}<label>From<input id="filter-from" type="date" value="${esc(filter.from)}"></label><label>Through<input id="filter-to" type="date" value="${esc(filter.to)}"></label><button class="quiet-button" id="apply-filter">Apply</button></div>`;}
 function bindFilters(){const select=$('#filter-project');if(!select)return;select.value=filter.project;$('#apply-filter').onclick=()=>{const f=$('#filter-from').value,t=$('#filter-to').value;if(f&&t&&f>t){notice('The start date must be on or before the end date.');return;}filter={project:select.value,from:f,to:t};render();};if($('#period'))$('#period').onchange=()=>{if($('#period').value==='all'){$('#filter-from').value='';$('#filter-to').value='';}if($('#period').value==='annual'){const year=Number($('#report-year').value);if(year>=2000&&year<=2100){$('#filter-from').value=year+'-01-01';$('#filter-to').value=year+'-12-31';}}};}
 function input(name,label,type='text',value='',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
 function select(name,label,options){return `<label>${label}<select name="${name}">${options}</select></label>`;}
 function projectInput(){return select('project','Project',projectOptions(false).replace(`value="${esc(activeProject||filter.project)}"`,`value="${esc(activeProject||filter.project)}" selected`));}
 async function modal(title,body,onSubmit){const d=$('#finance-dialog');previousFocus=document.activeElement;d.innerHTML=`<div class="detail-header"><div><div class="eyebrow">BROWSER DEMO</div><h2 id="finance-dialog-title">${title}</h2></div><button class="close-detail" aria-label="Close">×</button></div><form class="finance-form">${body}<p class="form-error wide" role="alert"></p><div class="form-actions"><button type="button" class="quiet-button" id="cancel-form">Cancel</button><button type="submit" class="gold-button">Save</button></div></form>`;d.querySelector('.close-detail').onclick=()=>d.close();$('#cancel-form').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(new FormData(e.target),e.target);d.close();render();notice('Saved on this browser.');}catch(err){d.querySelector('.form-error').textContent=err.message||'Could not save. Browser storage may be full.';}finally{b.disabled=false;}};d.showModal();document.body.classList.add('modal-open');}
 $('#finance-dialog').addEventListener('close',()=>{if(!projectDialog.open)document.body.classList.remove('modal-open');if(previousFocus?.isConnected)previousFocus.focus();else if(projectDialog.open)projectDialog.querySelector('[aria-selected="true"]').focus();});
 function positive(v){const n=Number(v);if(!Number.isFinite(n)||n<=0||n>1e12)throw new Error('Enter an amount above zero and below 1 trillion EGP.');return M.money(n);}
 function commonForm(){return projectInput()+input('date','Transaction date','date',today,'required')+input('amount','Amount · EGP','number','','required min="0.01" max="999999999999" step="0.01"')+input('description','Description','text','','required maxlength="500"');}
 function addPayment(){modal(direction==='in'?'Record client receipt':'Record supplier / technician payment',commonForm()+input('party',direction==='in'?'Received from':'Paid to','text','','required maxlength="150"')+select('method','Payment method',['Bank transfer','Cash','InstaPay','Cheque','Other'].map(s=>`<option>${s}</option>`).join(''))+input('reference','Receipt / payment reference','text','','required maxlength="100"')+'<p class="wide">Payments affect the cash ledger. Record the related expense or earned revenue separately; saving a payment does not create either.</p>',async f=>{const ref=String(f.get('reference')).trim();if(db.payments.some(p=>p.reference===ref))throw new Error('This payment reference already exists. Use a unique reference.');await change(n=>n.payments.push({id:id(),project:f.get('project'),date:f.get('date'),amount:positive(f.get('amount')),description:f.get('description'),party:f.get('party'),method:f.get('method'),reference:ref,direction}));});}
 function payments(){const rows=M.scope(db.payments.filter(r=>r.direction===direction),filter.project,filter.from,filter.to);const all=M.scope(db.payments,filter.project,filter.from,filter.to);const received=M.sum(all.filter(r=>r.direction==='in'),r=>r.amount),paid=M.sum(all.filter(r=>r.direction==='out'),r=>r.amount);return head('Payments ledger','Client receipts and outgoing payments remain separate.','<button class="gold-button" id="add-payment">+ Record payment</button>')+`<div class="finance-subtabs"><button class="quiet-button" data-direction="in" aria-pressed="${direction==='in'}">Client receipts</button><button class="quiet-button" data-direction="out" aria-pressed="${direction==='out'}">Supplier & technician payments</button></div>`+filters()+kpis([['Client receipts',received],['Outgoing payments',paid],['Net cash movement',M.money(received-paid)]])+table(['Date','Project','Counterparty','Description','Method / reference','Amount · EGP'],rows.map(r=>[esc(r.date),esc(projectName(r.project)),esc(r.party),esc(r.description),`${esc(r.method)}<small>${esc(r.reference)}</small>`,amount(r.amount)]))+'<div class="client-actions"><button id="export-payments">Download payment sheet</button></div>';}
 function expenseForm(){modal('Record an incurred expense',commonForm()+select('category','Cost category',['Materials','Technicians','Subcontractors','Transport','Design','Other direct costs','Overhead'].map(s=>`<option>${s}</option>`).join(''))+input('party','Supplier / technician','text','','required maxlength="150"')+input('reference','Invoice / expense reference','text','','required maxlength="100"')+'<p class="wide">This is an incurred cost, whether paid or unpaid. Record its cash payment in the payments ledger and save supporting documents in Invoices.</p>',async f=>{const ref=f.get('reference').trim();if(db.expenses.some(r=>r.reference===ref))throw new Error('This expense reference already exists.');await change(n=>n.expenses.push({id:id(),project:f.get('project'),date:f.get('date'),amount:positive(f.get('amount')),description:f.get('description'),category:f.get('category'),party:f.get('party'),reference:ref}));});}
 function chargeForm(){modal('Record a client charge',commonForm()+input('earned','Earned revenue included in this charge · EGP','number',0,'required min="0" step="0.01"')+'<p class="wide">Enter earned revenue only for work or fees earned by this date. A client advance or unearned charge is not earned revenue. This demo does not infer accounting treatment from a quotation.</p>',async f=>{const value=positive(f.get('amount')),earned=Number(f.get('earned'));if(!Number.isFinite(earned)||earned<0||earned>value)throw new Error('Earned revenue must be between zero and the charge amount.');await change(n=>n.charges.push({id:id(),project:f.get('project'),date:f.get('date'),amount:value,earned:M.money(earned),description:f.get('description')}));});}
 function expenses(){const rows=M.scope(db.expenses,filter.project,filter.from,filter.to),charges=M.scope(db.charges,filter.project,filter.from,filter.to);return head('Expenses & client charges','Incurred costs and earned revenue drive the P&L. Client charges drive statements.')+filters()+`<div class="client-actions"><button id="add-expense">+ Record expense</button><button id="add-charge">+ Record client charge</button></div><h3>Incurred expenses</h3>`+table(['Date','Project','Category','Supplier / technician','Description','Cost · EGP'],rows.map(r=>[esc(r.date),esc(projectName(r.project)),esc(r.category),esc(r.party),`${esc(r.description)}<small>${esc(r.reference)}</small>`,amount(r.amount)]))+`<h3 class="detail-section">Client charges</h3>`+table(['Date','Project','Description','Charged · EGP','Earned revenue · EGP'],charges.map(r=>[esc(r.date),esc(projectName(r.project)),esc(r.description),amount(r.amount),amount(r.earned)]));}
 function invoiceForm(){modal('Save an invoice / فاتورة',projectInput()+input('date','Invoice date','date',today,'required')+input('number','Invoice number','text','','required maxlength="100"')+input('party','Supplier / issuer','text','','required maxlength="150"')+input('amount','Invoice face value · EGP','number','','required min="0.01" step="0.01"')+select('linked','Related expense',`<option value="">Document only — not linked</option>${db.expenses.map(r=>`<option value="${esc(r.id)}">${esc(r.reference)} · ${esc(projectName(r.project))}</option>`).join('')}`)+input('file','Invoice file · PDF, JPG, PNG · up to 10 MB','file','','required accept="application/pdf,image/jpeg,image/png"')+'<p class="wide">Saving an invoice stores the supporting document only. It does not post an expense or payment again.</p>',async f=>{const file=f.get('file');if(!file||!['application/pdf','image/jpeg','image/png'].includes(file.type)||file.size>10*1024*1024||file.size===0)throw new Error('Choose a non-empty PDF, JPG or PNG no larger than 10 MB.');const project=f.get('project'),linked=f.get('linked');if(linked&&db.expenses.find(r=>r.id===linked)?.project!==project)throw new Error('The linked expense belongs to a different project.');if(db.invoices.some(r=>r.number===f.get('number')&&r.party===f.get('party')))throw new Error('This invoice number is already saved for this issuer.');const key=id();await change(n=>n.invoices.push({id:key,project,date:f.get('date'),number:f.get('number'),party:f.get('party'),amount:positive(f.get('amount')),linked,name:file.name,type:file.type,size:file.size}),{id:key,blob:file});});}
 function invoices(){const rows=M.scope(db.invoices,filter.project,filter.from,filter.to);return head('Invoice archive · الفواتير','Keep each supporting document with its project and expense.','<button class="gold-button" id="add-invoice">+ Save invoice</button>')+filters()+`<div class="document-grid">${rows.length?rows.map(r=>`<article class="document-card"><small>${esc(r.number)} · ${esc(r.date)}</small><h3>${esc(r.party)}</h3><p>${esc(projectName(r.project))}<br>EGP ${amount(r.amount)}</p><p>${esc(r.name)} · ${(r.size/1024).toFixed(0)} KB</p><p>${r.linked?'Linked to expense '+esc(db.expenses.find(x=>x.id===r.linked)?.reference):'Document only'}</p><button class="quiet-button" data-file="${r.id}">Download invoice</button></article>`).join(''):'<p class="empty">No invoices saved yet. Add a PDF or photo to try the archive.</p>'}</div>`;}
 async function getInvoice(key){try{const blob=await new Promise((resolve,reject)=>{const r=connection.transaction('files').objectStore('files').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(!blob)throw new Error('The invoice file is not available on this browser.');const r=db.invoices.find(r=>r.id===key);saveDownload(r.name,blob,r.type);}catch(e){notice(e.message);}}
 function pnlView(){const r=M.pnl(db,filter.project,filter.from,filter.to);return head('Profit & loss','Choose a project or all projects, then an annual or cumulative period.')+filters(false,true)+kpis([['Earned revenue',r.revenue],['Direct costs',r.direct],['Gross profit',r.gross],['Operating profit',r.profit]])+`<article class="report-paper" id="print-report"><div class="eyebrow">TRUST M · DEMO REPORT</div><h2>Operating profit & loss</h2><p class="finance-note">${esc(filter.project==='all'?'All projects':projectName(filter.project))} · ${esc(filter.from||'First recorded activity')} through ${esc(filter.to||'Latest recorded activity')} · EGP</p><div class="report-lines">${[['Earned revenue',r.revenue],['Direct project costs',r.direct],['Gross profit',r.gross],['Allocated overhead expenses',r.overhead],['Operating profit before tax',r.profit]].map(([l,v],i)=>`<div class="${i===4?'report-total':''}"><span>${l}</span><strong>${amount(v)}</strong></div>`).join('')}</div><p class="finance-note">Based on recorded earned revenue and incurred expenses in the selected period. Client receipts, outgoing payments, draft quotations and archived invoice files do not create additional profit or costs. No tax, depreciation, financing or unrecorded overhead entries are calculated automatically.</p></article><div class="client-actions"><button id="export-pnl">Download P&L sheet</button><button id="print-report-button">Print / save PDF</button></div>`;}
 function statements(){if(filter.project==='all')filter.project=db.projects[0].id;const s=M.statement(db,filter.project,filter.from,filter.to),p=db.projects.find(p=>p.id===filter.project);return head('Client statement · كشف حساب العميل','A dated record of charges, receipts, and the running account balance.')+filters(true)+`<article class="report-paper"><div class="eyebrow">TRUST M · SAMPLE CLIENT STATEMENT</div><h2>${esc(p.client)}</h2><p class="finance-note">${esc(p.name)} · ${esc(filter.from||'First recorded activity')} through ${esc(filter.to||'Latest activity')} · EGP</p><div class="report-lines"><div><span>Opening balance</span><strong>${amount(s.opening)}</strong></div></div>${table(['Date','Entry','Description','Charges','Receipts','Balance'],s.rows.map(r=>[esc(r.date),esc(r.type),esc(r.description),r.debit?amount(r.debit):'—',r.credit?amount(r.credit):'—',amount(r.balance)]))}<div class="report-lines"><div class="report-total"><span>${s.closing<0?'Client credit balance':'Balance to collect'}</span><strong>${amount(Math.abs(s.closing))}</strong></div></div><p class="finance-note">A positive balance is charged but unpaid; a negative balance is credit held for the client. This is an account balance, not an overdue assessment. Internal costs and profit are excluded.</p></article><div class="client-actions"><button id="export-statement">Download statement sheet</button><button id="print-report-button">Print / save PDF</button><button id="share-statement">Prepare email / WhatsApp</button></div>`;}
 function shareStatement(){const s=M.statement(db,filter.project,filter.from,filter.to),p=db.projects.find(p=>p.id===filter.project);modal('Share client statement',input('email','Client email','email','')+input('phone','WhatsApp number including country code','tel','')+`<label class="wide">Message<textarea name="message">${esc(`Hello ${p.client},\n\nPlease find your Trust M statement for ${p.name}, through ${filter.to||today}.\nOpening balance: EGP ${amount(s.opening)}\nCharges in period: EGP ${amount(s.charges)}\nReceipts in period: EGP ${amount(s.receipts)}\nClosing ${s.closing<0?'credit':'balance'}: EGP ${amount(Math.abs(s.closing))}\n\nThank you,\nTrust M\nSample statement — review before sending.`)}</textarea></label>`+select('channel','Open draft in','<option value="email">Email</option><option value="whatsapp">WhatsApp</option>')+'<p class="wide">Download the statement first and attach it manually in your messaging app. Contact details are not saved. You will press Send in that app.</p>',async f=>{const text=f.get('message');if(f.get('channel')==='email'){const email=f.get('email');if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid client email.');const a=document.createElement('a');a.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent('Trust M client statement')}&body=${encodeURIComponent(text)}`;a.click();}else{const phone=f.get('phone').replace(/[\s()+-]/g,'');if(!/^[1-9]\d{7,14}$/.test(phone))throw new Error('Enter an international WhatsApp number with country code.');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');}setTimeout(()=>notice('Draft requested in your messaging app. Nothing has been confirmed as sent.'),0);});$('#finance-dialog [type=submit]').textContent='Open draft';}
 function quoteView(){return head('Quotation builder · المقايسات','Build by reusable work blocks. Quantities, rates and fees calculate automatically.','<button class="gold-button" id="new-quote">+ New quotation</button>')+`<div class="quote-library">${db.blocks.map(b=>`<article class="document-card"><small>REUSABLE BLOCK · ${b.items.length} ITEMS</small><h3>${esc(b.name)}</h3><p>${b.items.slice(0,3).map(i=>esc(i.description)).join(' · ')}</p><button class="quiet-button" data-block="${b.id}">Use block</button></article>`).join('')}</div><div id="quote-editor"></div><h3 class="detail-section">Saved quotations</h3>`+table(['Quotation','Project','Date','Status','Total · EGP','Actions'],db.quotes.map(q=>[esc(q.reference),esc(projectName(q.project)),esc(q.date),esc(q.status),amount(M.quote(q).total),`<button data-quote="${q.id}">Open</button>`]));}
 function startQuote(){draft={id:id(),reference:'TM-DEMO-'+String(db.quotes.length+1).padStart(3,'0'),project:db.projects[0].id,date:today,fee:0,design:0,status:'Draft',items:[]};}
 function drawQuote(){if(!draft)return;$('#quote-editor').innerHTML=`<form class="quote-editor"><h3>${db.quotes.some(q=>q.id===draft.id)?'Edit quotation':'New quotation'}</h3><div class="quote-settings">${input('reference','Quotation reference','text',draft.reference,'required maxlength="100"')}${select('project','Project',projectOptions(false))}${input('date','Quotation date','date',draft.date,'required')}${select('status','Status',['Draft','Sent','Approved'].map(s=>`<option>${s}</option>`).join(''))}</div><p class="finance-note">Select a block above to insert its items, or add your own. Rates are editable demo allowances. Marking a quote Approved does not post charges or revenue.</p><div class="finance-table-wrap"><table class="finance-table quote-items"><thead><tr><th>Description</th><th>Unit</th><th>Quantity</th><th>Unit price · EGP</th><th>Line total</th><th>Action</th></tr></thead><tbody>${draft.items.map((item,i)=>`<tr data-line="${i}"><td><input class="description" aria-label="Description ${i+1}" data-field="description" value="${esc(item.description)}" required maxlength="2000"></td><td><input aria-label="Unit ${i+1}" data-field="unit" value="${esc(item.unit)}" required maxlength="30"></td><td><input aria-label="Quantity ${i+1}" data-field="quantity" type="number" min="0.001" step="0.001" value="${item.quantity}" required></td><td><input aria-label="Unit price ${i+1}" data-field="rate" type="number" min="0" max="999999999" step="0.01" value="${item.rate}" required></td><td class="num" data-line-total="${i}">${amount(M.money(item.quantity*item.rate))}</td><td><button type="button" data-remove="${i}">Remove</button></td></tr>`).join('')}</tbody></table></div><div class="client-actions"><button type="button" id="add-line">+ Add item</button><button type="button" id="save-block">Save items as reusable block</button></div><div class="quote-settings">${input('fee','Supervision fee · % of line subtotal','number',draft.fee,'required min="0" max="100" step="0.01"')}${input('design','Design fee · EGP','number',draft.design,'required min="0" max="999999999" step="0.01"')}</div><div class="quote-totals" id="quote-totals"></div><p class="finance-note">No automatic VAT calculation. These figures are a quotation, not a posted client balance or P&L revenue.</p><div class="client-actions"><button type="submit">Save quotation</button><button type="button" id="export-quote">Download quotation sheet</button></div><p class="form-error" role="alert" id="quote-error"></p></form>`;
 const form=$('#quote-editor form');form.elements.project.value=draft.project;form.elements.status.value=draft.status;
 function sync(){for(const key of ['reference','project','date','status'])draft[key]=form.elements[key].value;for(const key of ['fee','design'])draft[key]=Number(form.elements[key].value);form.querySelectorAll('[data-line]').forEach(row=>{const i=Number(row.dataset.line);row.querySelectorAll('[data-field]').forEach(input=>{draft.items[i][input.dataset.field]=['quantity','rate'].includes(input.dataset.field)?Number(input.value):input.value;});row.querySelector('[data-line-total]').textContent=amount(M.money(draft.items[i].quantity*draft.items[i].rate));});const q=M.quote(draft);$('#quote-totals').textContent=`Subtotal ${amount(q.base)} + supervision ${amount(q.fee)} + design ${amount(draft.design)} = EGP ${amount(q.total)}`;}
 function valid(){sync();if(!form.reportValidity())return false;if(!draft.items.length){$('#quote-error').textContent='Add at least one quotation item.';return false;}if(!Number.isFinite(M.quote(draft).total)||M.quote(draft).total<=0||M.quote(draft).total>1e12){$('#quote-error').textContent='Enter a valid quotation total above zero and below 1 trillion EGP.';return false;}return true;}
 form.addEventListener('input',sync);form.addEventListener('change',sync);sync();
 $('#add-line').onclick=()=>{sync();draft.items.push({description:'',unit:'Lump sum',quantity:1,rate:0});drawQuote();};
 form.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{sync();draft.items.splice(Number(b.dataset.remove),1);drawQuote();});
 form.onsubmit=async e=>{e.preventDefault();if(!valid())return;e.submitter.disabled=true;try{if(db.quotes.some(q=>q.id!==draft.id&&q.reference===draft.reference))throw new Error('This quotation reference already exists.');await change(n=>{const index=n.quotes.findIndex(q=>q.id===draft.id);if(index<0)n.quotes.push(structuredClone(draft));else n.quotes[index]=structuredClone(draft);});render();notice('Quotation saved. No client charge or revenue was posted.');}catch(err){$('#quote-error').textContent=err.message;}finally{if(e.submitter)e.submitter.disabled=false;}};
 $('#save-block').onclick=()=>{if(!valid())return;const items=structuredClone(draft.items);modal('Save reusable quotation block',input('name','Block name','text','','required maxlength="100"'),async f=>{await change(n=>n.blocks.push({id:id(),name:f.get('name'),items}));});};
 $('#export-quote').onclick=()=>{if(!valid())return;const totals=M.quote(draft);csvDownload(draft.reference,[['TRUST M QUOTATION · DEMO'],['Reference',draft.reference],['Project',projectName(draft.project)],['Date',draft.date],['Status',draft.status],['Description','Unit','Quantity','Unit price EGP','Total EGP'],...draft.items.map(i=>[i.description,i.unit,i.quantity,i.rate,M.money(i.quantity*i.rate)]),['Subtotal',totals.base],['Supervision %',draft.fee],['Supervision fee',totals.fee],['Design fee',draft.design],['Total EGP',totals.total],['Note','No automatic VAT calculation; this document does not post client charges or earned revenue.']]);};
 }
 function sourceNotice(){
 const ps=db.projects.filter(p=>(filter.project==='all'||p.id===filter.project)&&p.source);
 if(!ps.length)return '';
 const dated=Boolean(filter.from||filter.to);
 return `<p class="demo-notice" data-no-translate>بيانات مشروع مهندس احمد جاية من الملف الأصلي. تاريخ الدفعة وتاريخ اختبار العزل وتواريخ تحميل الحساب مش موجودين. ${dated?'الفترة المختارة بتستبعد الحركات اللي من غير تاريخ؛ اختار كل الحركات عشان يظهر رصيد الملف كامل.':'عرض كل الحركات بيشمل البنود اللي من غير تاريخ.'} الإيراد المكتسب لسه محتاج تأكيد، عشان كده الأرباح بتظهر بشرطة بدل رقم مفترض.</p>`;
 }
 function render(){
  $('#finance-status').textContent='';$('#finance-tabs').querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;});$('#finance-view').setAttribute('aria-labelledby','tab-'+tab);
  $('#finance-tabs').hidden=false;
  $('#finance-view').innerHTML=({sheet:financialSheet,projects:projectOverview,reports:reportCenter,payments,expenses,invoices,quotes:quoteView,pnl:pnlView,statements}[tab])();$('#finance-view').insertAdjacentHTML('afterbegin',sourceNotice());bindFilters();
  if(tab==='sheet')bindSheet();
  if(tab==='reports')bindReportCenter();
  if(tab==='projects'){
   const actions=document.createElement('div');actions.className='project-entry-actions';
   actions.innerHTML='<button class="gold-button" data-entry="receipt">+ Add Client Receipt</button><button class="quiet-button" data-entry="expense">+ Add Expense</button>';
   document.querySelector('.portfolio-heading').after(actions);
   function entry(kind,pid){const saved=filter.project;if(pid)filter.project=pid;if(kind==='receipt'){direction='in';addPayment();}else expenseForm();filter.project=saved;}
   actions.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>entry(b.dataset.entry));
   document.querySelectorAll('[data-project-open]').forEach(b=>{
    b.onclick=()=>openProjectFinance(b.dataset.projectOpen);
    const card=b.closest('article'),controls=document.createElement('div');controls.className='project-entry-actions card-entry-actions';
    controls.innerHTML='<button class="gold-button" data-entry="receipt">+ Add Client Receipt</button><button class="quiet-button" data-entry="expense">+ Add Expense</button>';
    b.before(controls);
    controls.querySelectorAll('[data-entry]').forEach(action=>action.onclick=()=>entry(action.dataset.entry,b.dataset.projectOpen));
    card.onclick=e=>{if(!e.target.closest('button'))openProjectFinance(b.dataset.projectOpen);};
   });
  }
  if($('#report-year'))$('#report-year').oninput=()=>{if($('#period').value==='annual')$('#period').onchange();};
  if(tab==='payments'){$('#add-payment').onclick=addPayment;document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{direction=b.dataset.direction;render();});$('#export-payments').onclick=()=>{const rows=M.scope(db.payments.filter(r=>r.direction===direction),filter.project,filter.from,filter.to);csvDownload('Trust-M-'+(direction==='in'?'client-receipts':'outgoing-payments'),[['TRUST M PAYMENT SHEET · DEMO'],['Period',filter.from||'First activity',filter.to||'Latest activity'],['Date','Project','Counterparty','Description','Method','Reference','EGP'],...rows.map(r=>[r.date,projectName(r.project),r.party,r.description,r.method,r.reference,r.amount]),['Total EGP',M.sum(rows,r=>r.amount)]]);};}
  if(tab==='expenses'){$('#add-expense').onclick=expenseForm;$('#add-charge').onclick=chargeForm;}
  if(tab==='invoices'){$('#add-invoice').onclick=invoiceForm;document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>getInvoice(b.dataset.file));}
  if(tab==='quotes'){$('#new-quote').onclick=()=>{startQuote();drawQuote();};document.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>{if(!draft)startQuote();draft.items.push(...structuredClone(db.blocks.find(x=>x.id===b.dataset.block).items));drawQuote();});document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>{draft=structuredClone(db.quotes.find(q=>q.id===b.dataset.quote));drawQuote();});drawQuote();}
  if(tab==='pnl')$('#export-pnl').onclick=()=>{const r=M.pnl(db,filter.project,filter.from,filter.to);csvDownload('Trust-M-P-and-L',[['TRUST M OPERATING P&L · DEMO'],['Project',filter.project==='all'?'All projects':projectName(filter.project)],['From',filter.from||'First activity'],['Through',filter.to||'Latest activity'],['Currency','EGP'],['Earned revenue',r.revenue],['Direct costs',r.direct],['Gross profit',r.gross],['Overheads',r.overhead],['Operating profit before tax',r.profit],['Basis','Recorded earned revenue less incurred expenses. Excludes unrecorded costs, automatic taxes, depreciation and financing.']]);};
  if(tab==='statements'){$('#export-statement').onclick=()=>{const s=M.statement(db,filter.project,filter.from,filter.to);csvDownload('Trust-M-client-statement',[['TRUST M CLIENT STATEMENT · DEMO'],['Project',projectName(filter.project)],['Client',db.projects.find(p=>p.id===filter.project).client],['From',filter.from||'First activity'],['Through',filter.to||'Latest activity'],['Opening EGP',s.opening],['Date','Entry','Description','Charges EGP','Receipts EGP','Balance EGP'],...s.rows.map(r=>[r.date,r.type,r.description,r.debit,r.credit,r.balance]),['Closing EGP',s.closing],['Note','Positive balance is unpaid charges; negative balance is client credit. Not an overdue assessment.']]);};$('#share-statement').onclick=shareStatement;}
  if($('#print-report-button'))$('#print-report-button').onclick=()=>window.print();
  if(projectDialog.open)drawProjectFinance();
 }
 const projectDialog=document.createElement('dialog');projectDialog.className='project-dialog finance-project-dialog';projectDialog.setAttribute('aria-labelledby','project-finance-title');document.body.append(projectDialog);
 let projectFocus;
 projectDialog.addEventListener('close',()=>{activeProject=null;document.body.classList.remove('modal-open');projectFocus?.focus();});
 const apartmentBreakdown=[['Plumbing','Foundation plumbing purchases',42021],['Plumbing','Concealed plumbing purchases',43000],['Plumbing','Material transport',600],['Electrical','First-fix electrical purchases',58877],['Electrical','Material transport',600],['Ceramics','Tile purchases',95161],['Demolition','Roof tiles & marble removal',4000],['Ceramics','Tile handling & storage',4500],['Site logistics','Sand relocation',3200],['Site logistics','Debris removal',2000],['Waterproofing','Waterproofing test',3000]];
 function projectData(pid){const payments=db.payments.filter(r=>r.project===pid),expenses=db.expenses.filter(r=>r.project===pid),charges=db.charges.filter(r=>r.project===pid);const receipts=M.sum(payments.filter(r=>r.direction==='in'),r=>r.amount),outgoing=M.sum(payments.filter(r=>r.direction==='out'),r=>r.amount),cost=M.sum(expenses,r=>r.amount),charged=M.sum(charges,r=>r.amount);return {payments,expenses,charges,receipts,outgoing,cost,charged,balance:M.money(charged-receipts),cash:M.money(receipts-outgoing),profit:M.pnl(db,pid,'',today),invoices:db.invoices.filter(r=>r.project===pid),quotes:db.quotes.filter(r=>r.project===pid)};}
 function detailedExpenses(pid){return db.expenses.filter(r=>r.project===pid).flatMap(r=>r.id==='EXP-001'&&r.amount===256959&&r.description==='Sample renovation costs'?apartmentBreakdown.map(([category,description,value],i)=>({...r,id:r.id+'-'+i,category,description,amount:value,reference:r.reference+' / '+String(i+1).padStart(2,'0'),detail:true})):[r]);}
 function metric(label,value,note='EGP'){return `<div class="project-metric"><span>${label}</span><strong>${amount(value)}</strong><small>${note}</small></div>`;}
 function projectOverview(){const allReceipts=M.sum(db.payments.filter(r=>r.direction==='in'),r=>r.amount),allCosts=M.sum(db.expenses,r=>r.amount),allCharges=M.sum(db.charges,r=>r.amount);return `<div class="portfolio-heading"><div><div class="eyebrow">PROJECT FINANCIALS</div><h2>One project. The complete picture.</h2><p>Open a project to inspect its statement, supporting documents and quotation blocks.</p></div><span class="subtle">${db.projects.length} project files · EGP</span></div><div class="portfolio-totals">${metric('Client receipts',allReceipts)}${metric('Recorded project costs',allCosts)}${metric('Charges to clients',allCharges)}${metric('Net client account balance',M.money(allCharges-allReceipts))}</div><div class="financial-project-grid">${db.projects.map((p,i)=>{const d=projectData(p.id),ratio=d.charged?Math.min(100,d.receipts/d.charged*100):0,groups=[...new Set(detailedExpenses(p.id).map(e=>e.category))];return `<article class="financial-project-card"><div class="project-card-top"><span class="file-number">FILE ${String(i+1).padStart(2,'0')}</span><span class="account-badge ${d.balance>0?'due':'credit'}">${d.balance>0?'Balance to collect':d.balance<0?'Client credit':'Account settled'}</span></div><h3>${esc(p.name.replace(' · Demo',''))}</h3><p class="project-client">${esc(p.client)} <span>·</span> ${p.type||(p.id==='apartment'?'Renovation & supervision':'Pool construction')}</p><div class="project-collection"><span>Receipts against recorded charges</span><strong>${d.charged?(d.receipts/d.charged*100).toFixed(1):'0.0'}%</strong></div><div class="progress"><span style="width:${ratio}%"></span></div><div class="project-card-metrics">${metric('Charged to client',d.charged)}${metric('Payments received',d.receipts)}${metric('Recorded costs',d.cost)}${metric(d.balance<0?'Client credit':'Balance to collect',Math.abs(d.balance))}</div><div class="project-scope-tags">${groups.slice(0,6).map(g=>`<span>${esc(g)}</span>`).join('')}</div><div class="file-inventory"><span>${detailedExpenses(p.id).length} expense lines</span><span>${d.payments.length} payments</span><span>${d.invoices.length} invoices</span><span>${d.quotes.length} quotations</span></div><button class="open-project-finance" data-project-open="${esc(p.id)}">Open complete project file <span>↗</span></button></article>`;}).join('')}</div><div class="financial-bottom-note"><span>01 / Review the overview</span><span>02 / Open the project file</span><span>03 / Record, document, report</span></div>`;}
 function openProjectFinance(pid){activeProject=pid;projectTab='summary';projectFocus=document.activeElement;drawProjectFinance();projectDialog.showModal();document.body.classList.add('modal-open');}
 const projectSections=[['summary','Overview'],['statement','Expense statement'],['payments','Payments'],['documents','Invoices'],['blocks','Quotation blocks'],['profit','P&L']];
 function drawProjectFinance(){
  const p=db.projects.find(p=>p.id===activeProject);if(!p)return;const d=projectData(p.id),lines=detailedExpenses(p.id),groups={};lines.forEach(r=>groups[r.category]=(groups[r.category]||0)+r.amount);
  let content='';
  if(projectTab==='summary')content=`<div class="project-modal-overview"><div><div class="modal-section-title"><div class="eyebrow">FINANCIAL POSITION</div><h3>From costs to client balance</h3></div><div class="project-waterfall">${[['Recorded project expenses',d.cost],['Additional client charges above costs',M.money(d.charged-d.cost)],['Total charged to client',d.charged],['Less: client receipts',-d.receipts],[d.balance<0?'Closing client credit':'Closing balance to collect',Math.abs(d.balance)]].map(([l,v],i)=>`<div class="${i===4?'final-balance':''}"><span>${l}</span><strong>${amount(v)}</strong></div>`).join('')}</div><p class="finance-note">The difference between charges and costs can include fees and billing timing. It is not automatically a profit calculation.</p></div><aside class="project-cost-panel"><div class="eyebrow">COST COMPOSITION</div><h3>Where the money goes</h3>${Object.entries(groups).map(([g,n])=>`<div class="cost-composition"><div><span>${esc(g)}</span><strong>${amount(n)}</strong></div><div class="balance-track"><span style="width:${d.cost?n/d.cost*100:0}%"></span></div></div>`).join('')||'<p class="finance-note">No costs recorded yet.</p>'}</aside></div><div class="project-modal-quick">${metric('Cash received',d.receipts)}${metric('Cash paid out',d.outgoing)}${metric('Net recorded cash movement',d.cash)}${metric('Operating profit to date',d.profit.profit)}</div><div class="project-action-row"><button data-action="receipt">+ Client receipt</button><button data-action="expense">+ Expense</button><button data-action="invoice">+ Save invoice</button><button data-action="quotation">Create quotation from blocks</button></div><div class="project-note-box"><h3>Review notes</h3><p>${p.source?esc((db.sheetNotes?.[p.id]||[]).map(n=>n.text).join(' · ')):p.id==='apartment'?'The sample cost breakdown follows the expense-sheet categories. Supervision and drawings are listed separately in the statement. Returns, refunds and missing transport charges need their own confirmed records before they change totals.':'Quotation blocks remain separate from actual costs. Confirm the quantities, supplier prices and approval status before posting any client charge.'}</p><p>Invoices saved: ${d.invoices.length}. Payments without document matching remain unverified; this demo does not reconcile bank transactions automatically.</p></div>`;
  if(projectTab==='statement')content=`<div class="modal-section-title"><div><div class="eyebrow">DETAILED PROJECT ACCOUNT</div><h3>Expense statement · كشف المصروفات</h3><p>Line-by-line expenditure, service fees, receipts and the client account.</p></div><button class="quiet-button" data-action="export-detail">Download detailed sheet</button></div><div class="statement-chapter"><span>01</span><div><h3>Client receipts · المستلم</h3><p>Money received from the client</p></div><strong>${amount(d.receipts)} <small>EGP</small></strong></div>${table(['Date','Payment reference','Description','Method','Received · EGP'],d.payments.filter(r=>r.direction==='in').map(r=>[esc(r.date),esc(r.reference),esc(r.description),esc(r.method),amount(r.amount)]))}<div class="statement-chapter"><span>02</span><div><h3>Expenses · المنصرف</h3><p>Detailed cost categories and supporting references</p></div><strong>${amount(d.cost)} <small>EGP</small></strong></div>${table(['No.','Date','Category','Description','Supplier / reference','Record status','Amount · EGP'],lines.map((r,i)=>[String(i+1).padStart(2,'0'),esc(r.date),esc(r.category),esc(r.description),`${esc(r.party)}<small>${esc(r.reference)}</small>`,r.sourceRow?esc(r.status):r.detail?'Demo cost breakdown':'Recorded',amount(r.amount)]))}${lines.some(r=>r.detail)?'<p class="finance-note source-detail-note">The 11 sample breakdown lines total the existing EGP 256,959 expense record; they are not added on top of it. Dates and supplier details are demo fields, not extracted invoice evidence.</p>':''}<div class="statement-chapter"><span>03</span><div><h3>Client charges & fees · الأتعاب</h3><p>Charges actually posted to the client account</p></div><strong>${amount(d.charged)} <small>EGP</small></strong></div>${table(['Date','Charge / service','Charged · EGP','Earned revenue · EGP'],d.charges.map(r=>[esc(r.date),esc(r.description),amount(r.amount),amount(r.earned)]))}<div class="statement-close"><div><span>Total charged</span><strong>${amount(d.charged)}</strong></div><div><span>Less received</span><strong>${amount(d.receipts)}</strong></div><div><span>${d.balance<0?'Client credit':'Balance to collect'}</span><strong>${amount(Math.abs(d.balance))}</strong></div></div><div class="project-action-row"><button data-action="receipt">+ Record receipt</button><button data-action="charge">+ Record client charge</button><button data-action="statement">Client-facing statement & sharing</button></div>`;
  if(projectTab==='payments')content=`<div class="modal-section-title"><div><div class="eyebrow">CASH LEDGER</div><h3>Every receipt and payment</h3><p>Receipts and outgoing payments stay in separate records.</p></div></div><div class="project-modal-quick">${metric('Client receipts',d.receipts)}${metric('Outgoing payments',d.outgoing)}${metric('Net cash movement',d.cash)}</div><div class="statement-chapter"><span>01</span><h3>Client receipts</h3></div>${table(['Date','From','Description','Method / reference','EGP'],d.payments.filter(r=>r.direction==='in').map(r=>[esc(r.date),esc(r.party),esc(r.description),`${esc(r.method)}<small>${esc(r.reference)}</small>`,amount(r.amount)]))}<div class="project-action-row"><button data-action="receipt">+ Record receipt</button><button data-action="export-receipts">Download receipts sheet</button></div><div class="statement-chapter"><span>02</span><h3>Supplier & technician payments</h3></div>${table(['Date','Paid to','Description','Method / reference','EGP'],d.payments.filter(r=>r.direction==='out').map(r=>[esc(r.date),esc(r.party),esc(r.description),`${esc(r.method)}<small>${esc(r.reference)}</small>`,amount(r.amount)]))}<div class="project-action-row"><button data-action="payment">+ Record payment</button><button data-action="export-outgoing">Download outgoing sheet</button></div>`;
  if(projectTab==='documents')content=`<div class="modal-section-title"><div><div class="eyebrow">SUPPORTING DOCUMENTS</div><h3>Invoices & receipts · الفواتير</h3><p>Documents saved under this project only.</p></div><button class="gold-button" data-action="invoice">+ Save invoice</button></div><div class="document-grid">${d.invoices.length?d.invoices.map(r=>`<article class="document-card"><small>${esc(r.date)} · ${esc(r.number)}</small><h3>${esc(r.party)}</h3><p>EGP ${amount(r.amount)}</p><p>${esc(r.name)}</p><p>${r.linked?'Linked to '+esc(db.expenses.find(e=>e.id===r.linked)?.reference):'Document only'}</p><button class="quiet-button" data-project-file="${r.id}">Download original</button></article>`).join(''):'<div class="invoice-empty"><span>DOCUMENT ARCHIVE</span><h3>A place for every invoice.</h3><p>Save supplier invoices, material receipts and technician documents as PDF, JPG or PNG. Link them to a recorded expense to keep the project file traceable.</p><button class="gold-button" data-action="invoice">Save the first invoice</button></div>'}</div>`;
  if(projectTab==='blocks')content=`<div class="modal-section-title"><div><div class="eyebrow">BUILD THE SCOPE, BLOCK BY BLOCK</div><h3>Quotation blocks · بنود المقايسة</h3><p>Start with a work package, then refine quantities, rates and fees.</p></div></div><div class="quote-library">${db.blocks.map(b=>`<article class="document-card"><small>${b.items.length} LINE ITEMS</small><h3>${esc(b.name)}</h3><div class="block-preview">${b.items.slice(0,4).map(i=>`<div><span>${esc(i.description)}</span><small>${i.quantity} ${esc(i.unit)}</small></div>`).join('')}</div><button class="quiet-button" data-project-block="${b.id}">Build quotation with this block</button></article>`).join('')}</div><div class="statement-chapter"><span>↳</span><h3>Project quotations</h3></div>${table(['Reference','Date','Status','Total · EGP',''],d.quotes.map(q=>[esc(q.reference),esc(q.date),esc(q.status),amount(M.quote(q).total),`<button data-project-quote="${q.id}">Open quotation</button>`]))}<p class="finance-note">A quotation total is not a cost, a receipt or earned revenue. Approval does not automatically post financial entries.</p>`;
  if(projectTab==='profit')content=`<div class="modal-section-title"><div><div class="eyebrow">PROJECT PERFORMANCE</div><h3>Operating profit & loss</h3><p>All recorded activity through ${esc(today)} · EGP</p></div><button class="quiet-button" data-action="pnl">Choose reporting period / export</button></div><div class="project-waterfall">${[['Earned revenue',d.profit.revenue],['Direct project costs',d.profit.direct],['Gross profit',d.profit.gross],['Allocated overhead',d.profit.overhead],['Operating profit before tax',d.profit.profit]].map(([l,v],i)=>`<div class="${i===4?'final-balance':''}"><span>${l}</span><strong>${amount(v)}</strong></div>`).join('')}</div><div class="project-note-box"><h3>How this report is calculated</h3><p>Earned revenue is explicitly recorded against client charges. Incurred expenses count when recorded, whether paid or unpaid. Client advances, quotations and invoice attachments do not create profit. Taxes, financing and unrecorded costs are excluded.</p></div>`;
  projectDialog.innerHTML=`<div class="project-file-header"><div><div class="eyebrow">TRUST M / PROJECT FINANCIAL FILE / DEMO</div><h2 id="project-finance-title">${esc(p.name.replace(' · Demo',''))}</h2><p>${esc(p.client)} · EGP · Browser-local records${p.source?' · مستورد من الملف الأصلي':''}</p></div><button class="close-detail" aria-label="Close project financial file">×</button></div><div class="project-file-nav" role="tablist" aria-label="Project financial sections">${projectSections.map(([key,label])=>`<button id="project-tab-${key}" role="tab" aria-controls="project-file-content" aria-selected="${key===projectTab}" tabindex="${key===projectTab?0:-1}" data-project-section="${key}">${label}</button>`).join('')}</div><section class="project-file-content" id="project-file-content" role="tabpanel" aria-labelledby="project-tab-${projectTab}">${p.accountingPending?'<p class="finance-note" data-no-translate>الإيراد المكتسب لسه محتاج تأكيد؛ الربح غير محسوب. التواريخ والخانات الناقصة في المصدر فضلت فاضية.</p>':''}${content}</section>`;
  projectDialog.querySelector('.close-detail').onclick=()=>projectDialog.close();
  projectDialog.querySelectorAll('[data-project-section]').forEach(b=>b.onclick=()=>{projectTab=b.dataset.projectSection;drawProjectFinance();projectDialog.querySelector(`[data-project-section="${projectTab}"]`).focus();});
  projectDialog.querySelector('.project-file-nav').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const bs=[...projectDialog.querySelectorAll('[data-project-section]')],i=bs.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?bs.length-1:(i+(e.key==='ArrowRight'?1:-1)+bs.length)%bs.length;bs[next].click();};
  function go(section){const pid=activeProject;projectDialog.close();filter.project=pid;filter.from='';filter.to='';tab=section;render();}
  function quoteForProject(block,existing){const pid=activeProject;projectDialog.close();tab='quotes';if(existing)draft=structuredClone(existing);else{startQuote();draft.project=pid;if(block)draft.items=structuredClone(block.items);}render();$('#quote-editor').scrollIntoView({block:'start',behavior:'smooth'});}
  projectDialog.querySelectorAll('[data-project-file]').forEach(b=>b.onclick=()=>getInvoice(b.dataset.projectFile));
  projectDialog.querySelectorAll('[data-project-block]').forEach(b=>b.onclick=()=>quoteForProject(db.blocks.find(x=>x.id===b.dataset.projectBlock)));
  projectDialog.querySelectorAll('[data-project-quote]').forEach(b=>b.onclick=()=>quoteForProject(null,db.quotes.find(x=>x.id===b.dataset.projectQuote)));
  projectDialog.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;if(action==='receipt'){direction='in';addPayment();}if(action==='payment'){direction='out';addPayment();}if(action==='expense')expenseForm();if(action==='charge')chargeForm();if(action==='invoice')invoiceForm();if(action==='quotation')quoteForProject();if(action==='statement')go('statements');if(action==='pnl')go('pnl');if(action==='export-detail')csvDownload('Trust-M-project-expense-statement',[['TRUST M DETAILED PROJECT STATEMENT · DEMO'],['Project',p.name],['Client',p.client],['Expense date','Category','Description','Reference','Amount EGP'],...lines.map(r=>[r.date,r.category,r.description,r.reference,r.amount]),['Total costs',d.cost],[],['Client charge date','Description','Charged EGP'],...d.charges.map(r=>[r.date,r.description,r.amount]),['Total charged',d.charged],['Client receipts',d.receipts],['Client account balance',d.balance],['Note','Internal owner statement. Detailed sample lines replace the sample aggregate for presentation only; do not add both.']]);if(action.startsWith('export-')&&action!=='export-detail'){const kind=action==='export-receipts'?'in':'out';csvDownload('Trust-M-project-'+(kind==='in'?'receipts':'payments'),[['TRUST M · DEMO PAYMENT SHEET'],['Project',p.name],['Date','Counterparty','Description','Reference','Amount EGP'],...d.payments.filter(r=>r.direction===kind).map(r=>[r.date,r.party,r.description,r.reference,r.amount])]);}});
 }
 function sheetRows(){
  if(filter.project==='all')filter.project=db.projects[0].id;
  const pid=filter.project;
  let running=0;
  return [...db.payments.filter(r=>r.project===pid&&r.direction==='in').map(r=>({...r,kind:r.sourceRow?r.method:'Client receipt',received:r.amount,expense:0,source:r.id})),...detailedExpenses(pid).map(r=>({...r,kind:r.category,received:0,expense:r.amount,source:r.detail?'EXP-001':r.id}))].sort((a,b)=>(a.sourceRow&&b.sourceRow?a.sourceRow-b.sourceRow:a.sourceRow?-1:b.sourceRow?1:a.date.localeCompare(b.date)||a.id.localeCompare(b.id))).map(r=>{running=M.money(running+r.received-r.expense);return {...r,running};});
 }
 function financialSheet(){
  const rows=sheetRows(),p=db.projects.find(p=>p.id===filter.project),d=projectData(p.id);
  const fee=M.sum(d.charges.filter(r=>r.chargeType==='supervision'||/^Supervision fee/i.test(r.description)),r=>r.amount),design=M.sum(d.charges.filter(r=>r.chargeType==='design'||/^Engineering drawings/i.test(r.description)),r=>r.amount);
  const arabic={'Client receipt':'مبلغ مستلم من العميل','Plumbing':'سباكة','Electrical':'كهرباء','Ceramics':'سيراميك','Demolition':'تكسير','Site logistics':'تشوينات','Waterproofing':'عزل','Materials':'خامات','Subcontractors':'مقاولون','Overhead':'مصروفات إدارية'};
  const descriptions={'Client advance':'دفعة مستلمة من العميل','Project advance':'دفعة مقدمة للمشروع','Foundation plumbing purchases':'مشتريات سباكة تأسيس','Concealed plumbing purchases':'مشتريات دفن','Material transport':'نقل خامات','First-fix electrical purchases':'مشتريات كهرباء تأسيس','Tile purchases':'مشتريات سيراميك','Roof tiles & marble removal':'تكسير بلاط السطح والرخام','Tile handling & storage':'تشوين السيراميك','Sand relocation':'نقل رملة من السطح','Debris removal':'جمع المخلفات','Waterproofing test':'اختبار عزل','Civil work completed':'أعمال مدنية منفذة'};
  const section=(receipt)=>{const selected=rows.map((r,index)=>({...r,index})).filter(r=>receipt?r.received>0:r.expense>0);return `<div class="excel-scroll" tabindex="0" role="region" aria-label="${receipt?'المبالغ المستلمة':'المصروفات'}"><table class="excel-sheet arabic-sheet" dir="rtl"><thead><tr>${['م','التاريخ','البيان','الفئة','منصرف','حالة البند','مستلم'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${selected.length?selected.map((r,i)=>{const docs=db.invoices.filter(f=>f.linked===r.source);return `<tr><th scope="row">${r.sourceRow?(r.serial??(r.received?1:'')):i+1}</th><td dir="ltr">${esc(r.date)}</td><td><button data-sheet-row="${r.index}" dir="auto" ${r.sourceRow?'data-no-translate':''}>${esc(r.sourceRow?r.description:descriptions[r.description]||r.description)}</button>${docs.length?`<div class="sheet-document-links">${docs.map(f=>`<button data-sheet-invoice="${f.id}">فاتورة ${esc(f.number)}</button>`).join(' · ')}</div>`:''}</td><td dir="auto" ${r.sourceRow?'data-no-translate':''}>${esc(r.sourceRow?r.kind:arabic[r.kind]||r.kind)}</td><td class="num" dir="ltr">${r.expense?amount(r.expense):'—'}</td><td>${esc(r.sourceRow?r.status:r.received?'تم الاستلام':r.detail?'تفصيل تجريبي':'مسجل')}</td><td class="num receipt-cell" dir="ltr">${r.received?amount(r.received):'—'}</td></tr>`;}).join(''):`<tr><td colspan="7" class="empty">${receipt?'لا توجد دفعات مستلمة بعد':'لا توجد مصروفات مسجلة بعد'}</td></tr>`}</tbody><tfoot><tr><th colspan="4" scope="row">${receipt?'إجمالي المسدد':'إجمالي المصروفات'}</th><td class="num" dir="ltr">${receipt?'—':amount(d.cost)}</td><td></td><td class="num" dir="ltr">${receipt?amount(d.receipts):'—'}</td></tr></tfoot></table></div>`;};
  return `<div class="arabic-workspace" dir="rtl" lang="ar"><div class="sheet-heading"><div><div class="eyebrow">TRUST M</div><h2>${p.source?esc(p.name):'كشف مصروفات المشروع'}</h2><p>المستلم · المنصرف · الأتعاب · رصيد العميل</p></div><label>المشروع<select id="sheet-project">${projectOptions(false)}</select></label><button class="quiet-button" id="sheet-export">تنزيل كشف الحساب</button></div>${p.source?'<p class="sheet-explanation" data-no-translate>البيانات مستوردة من ملف الإكسيل ومربوطة بالمشروع. أي دفعة أو مصروف جديد بيتحفظ على نفس المشروع. <a href="local-source/ahmed-original.xlsx" download>تنزيل الملف الأصلي</a></p>':''}<div class="sheet-client"><strong dir="auto">${esc(p.client)}</strong><span dir="auto">${esc(p.name)} · جميع الحركات المسجلة · جنيه مصري</span></div><div class="arabic-section-heading"><div><span>١</span><h3>المبالغ المستلمة من العميل</h3></div><button data-sheet-action="receipt" class="gold-button">+ إضافة مبلغ مستلم</button></div>${section(true)}<div class="arabic-section-heading"><div><span>٢</span><h3>يخصم منه — المصروفات</h3></div><button data-sheet-action="expense" class="gold-button">+ إضافة مصروف</button></div>${section(false)}<p class="sheet-explanation">المصروفات تمثل التكلفة المسجلة وقد تتضمن مبالغ لم تُدفع بعد. مدفوعات الموردين والفنيين في سجل مستقل أسفل الكشف لتجنب احتساب التكلفة مرتين. اضغط على البيان لعرض التفاصيل.</p><div class="arabic-summary-grid"><section class="arabic-account-summary"><h3>ملخص الحساب</h3>${[['إجمالي المصروفات',d.cost],['أتعاب الإشراف المسجلة',fee],['الرسومات الهندسية المسجلة',design],['فرق الفوترة والتكلفة / بنود أخرى',M.money(d.charged-d.cost-fee-design)],['الإجمالي الكلي المحمل على العميل',d.charged],['إجمالي المسدد من العميل',d.receipts],[d.balance<0?'رصيد دائن للعميل':'المتبقي المطلوب من العميل',Math.abs(d.balance)]].map(([label,value],i)=>`<div class="${i===6?'sheet-closing':i===4?'sheet-subtotal':''}"><span>${label}</span><strong dir="ltr">${amount(value)}</strong></div>`).join('')}<p class="sheet-explanation">الأتعاب المعروضة مسجلة بالفعل وليست مبالغ إضافية. ${p.id==='apartment'?'يتضمن المثال أتعاب إشراف بنسبة ١٥٪ من ٢٥٦٬٩٥٩ جنيه.':''} لا يُطبّق أي معدل جديد تلقائيًا على البيانات المحفوظة.</p></section><section class="pending-sheet-notes"><h3>النواقص والتسويات المعلقة</h3><p>ملاحظات للمراجعة فقط — لا تغيّر الإجمالي حتى تسجيل التسوية المالية.</p><div id="sheet-notes-list">${(db.sheetNotes?.[p.id]||[]).map(n=>`<div class="pending-note"><span>${esc(n.date)}</span><p dir="auto">${esc(n.text)}</p></div>`).join('')||'<div class="pending-note">لا توجد ملاحظات محفوظة لهذا المشروع.</div>'}</div><label>ملاحظة جديدة<textarea id="sheet-note" rows="3" maxlength="1000" placeholder="مثال: مراجعة قيمة مرتجع أو فاتورة ناقصة"></textarea></label><button class="quiet-button" id="save-sheet-note">حفظ الملاحظة</button><p class="sheet-explanation" ${p.source?'hidden':''}>أمثلة من الملف المرجعي: مرتجع كرتونتي سيراميك، مراجعة رد ١٬٠٠٠ جنيه حجز السيراميك، وقيمة نقل السيراميك. هذه أمثلة وليست تسويات مسجلة في المشروع التجريبي.</p></section></div><section class="sheet-capabilities"><h3>أدوات المشروع</h3><div class="sheet-action-grid">${[['receipt','إضافة مبلغ مستلم','تسجيل دفعة من العميل'],['expense','إضافة مصروف','تسجيل تكلفة على المشروع'],['payment','مدفوعات الموردين والفنيين','تسجيل المنصرف النقدي'],['invoices','الفواتير والمستندات','حفظ الفواتير وربطها بالمصروفات'],['quotes','المقايسات الجاهزة','بناء المقايسة من بنود مسبقة'],['statements','كشف حساب العميل','تنزيل الكشف أو تجهيز مشاركته'],['reports','التقارير المالية · 18','أرباح وتكاليف وحركة نقدية'],['detail','ملف المشروع الكامل','عرض جميع التفاصيل']].map(([key,title,note])=>`<button data-sheet-action="${key}"><strong>${title}</strong><span>${note}</span></button>`).join('')}</div></section></div>`;
 }

 function bindSheet(){
  $('#save-sheet-note').onclick=async()=>{const text=$('#sheet-note').value.trim();if(!text){notice('اكتب الملاحظة أولاً.');return;}const pid=filter.project;$('#save-sheet-note').disabled=true;try{await change(n=>{n.sheetNotes??={};n.sheetNotes[pid]??=[];n.sheetNotes[pid].push({date:today,text});});render();notice('تم حفظ الملاحظة دون تغيير الأرصدة.');}catch{notice('تعذر الحفظ. حاول مرة أخرى.');$('#save-sheet-note').disabled=false;}};
  $('#sheet-project').value=filter.project;$('#sheet-project').onchange=e=>{filter.project=e.target.value;render();};
  document.querySelectorAll('[data-sheet-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.sheetAction;if(a==='receipt'){direction='in';addPayment();}else if(a==='expense')expenseForm();else if(a==='payment'){direction='out';addPayment();}else if(a==='detail')openProjectFinance(filter.project);else{if(a==='quotes'){startQuote();draft.project=filter.project;}tab=a;render();}});
  document.querySelectorAll('[data-sheet-invoice]').forEach(b=>b.onclick=()=>getInvoice(b.dataset.sheetInvoice));
  document.querySelectorAll('[data-sheet-row]').forEach(b=>b.onclick=()=>{const r=sheetRows()[Number(b.dataset.sheetRow)];modal('Financial entry details',`<dl class="wide entry-details">${[['Date',r.date],['Project',projectName(filter.project)],['Description',r.description],['Category',r.kind],['Counterparty',r.party||'Not recorded'],['Reference',r.reference||'Not recorded'],['Received · EGP',amount(r.received)],['Expense · EGP',amount(r.expense)],['Status',r.sourceRow?(r.status||'الخانة فاضية في الملف'):r.detail?'Illustrative breakdown of the existing aggregate cost':'Recorded'],['المصدر',r.sourceRow?`${TrustSourceData.filename} · ${TrustSourceData.sheet} · السطر ${r.sourceRow}`:'إدخال من النظام']].map(([l,v])=>`<div><dt>${l}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`,async()=>{});$('#finance-dialog [type="submit"]').hidden=true;$('#cancel-form').textContent='Close';});
  $('#sheet-export').onclick=()=>{const d=projectData(filter.project);csvDownload('Trust-M-project-financial-sheet',[['TRUST M · PROJECT FINANCIAL SHEET · DEMO'],['Project',projectName(filter.project)],['Basis','All recorded activity. Running balance is receipts less incurred expenses, not a bank balance.'],['Date','Description','Category','Received EGP','Expense EGP','Running balance EGP'],...sheetRows().map(r=>[r.date,r.description,r.kind,r.received,r.expense,r.running]),['Total expenses',d.cost],['Client charges',d.charged],['Client receipts',d.receipts],['Client account balance',d.balance]]);};
 }
 let selectedReport='pnl';
 function reportCenter(){const report=TrustReports.build(db,selectedReport,filter.project,filter.from,filter.to);return head('Reports centre','18 reports from the records saved in this financial workspace.')+filters(false,true)+`<div class="report-centre"><aside class="report-menu no-print">${[...new Set(TrustReports.catalog.map(r=>r.group))].map(group=>`<h3>${group}</h3>${TrustReports.catalog.filter(r=>r.group===group).map(r=>`<button data-report="${r.id}" aria-pressed="${r.id===selectedReport}">${r.title}</button>`).join('')}`).join('')}</aside><div class="report-results"><article class="report-paper"><div class="eyebrow">TRUST M · DEMO RECORDS</div><h2>${esc(report.title)}</h2><p class="finance-note">${esc(filter.project==='all'?'All projects':projectName(filter.project))} · ${esc(selectedReport==='client-balances'?'All activity':filter.from||'First recorded activity')} through ${esc(filter.to||'Latest recorded activity')} · EGP unless stated</p><p class="report-basis">${esc(report.note)}</p>${table(report.headers.map(esc),report.rows.map(row=>row.map((v,i)=>report.numeric.includes(i)?v===null?'—':amount(v):esc(v))))}</article><div class="client-actions"><button id="download-centre-report">Download report sheet</button><button id="print-report-button">Print / save PDF</button></div><div class="report-foundation no-print"><h3>Reports that need more accounting records</h3><p>Balance sheet, trial balance and general ledger need a chart of accounts, opening balances and balanced journal entries. Aging reports need due dates and invoice-level payment allocations. Tax reports need confirmed tax codes and jurisdiction. Budget variance needs approved cost budgets. These are not included in the 18 reports above.</p></div></div></div>`;}
 function bindReportCenter(){document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{selectedReport=b.dataset.report;render();});$('#download-centre-report').onclick=()=>{const r=TrustReports.build(db,selectedReport,filter.project,filter.from,filter.to);csvDownload('Trust-M-'+selectedReport,[['TRUST M · '+r.title+' · DEMO'],['Project',filter.project==='all'?'All projects':projectName(filter.project)],['From',selectedReport==='client-balances'?'All activity':filter.from||'First recorded activity'],['Through',filter.to||'Latest recorded activity'],['Basis',r.note],['Currency','EGP unless stated'],[],r.headers,...r.rows]);};}
 render();
})();
